      rows.push({th, ri, ro, side, Ht, sec:[at(0, 0.9), at(0.08, 2.4), at(0.47, 0.42*Ht), at(0.47, 0.42*Ht + 3.8*side + 0.01), at(0.52, 0.48*Ht + 3.8*side), at(1.0, Ht)], at});
