    // rows of seats (thin step lines) and radial aisles
    { const o = B.p('#8592a3'); for (let i = 0; i < N; i += 1){ const r = rows[i], q = rows[(i+1) % N]; for (const s of [0.16, 0.24, 0.32, 0.40, 0.62, 0.72, 0.82, 0.92]){ const a = r.at(s, 0), b = q.at(s, 0);
        const ya = s < 0.47 ? lerp(0.9, 0.42*r.Ht, s/0.47) : lerp(0.48*r.Ht + 3.8*r.side, r.Ht, (s - 0.52)/0.48), yb = s < 0.47 ? lerp(0.9, 0.42*q.Ht, s/0.47) : lerp(0.48*q.Ht + 3.8*q.side, q.Ht, (s - 0.52)/0.48);
        segP(o, [a[0], ya + 0.25, a[2]], [b[0], yb + 0.25, b[2]], 0.12, 3); } }
      const w = B.p('#c9ccd0'); for (let i = 0; i < N; i += 6){ const r = rows[i]; for (let k = 0; k < 5; k++) if (k !== 2) segP(w, [r.sec[k][0], r.sec[k][1] + 0.3, r.sec[k][2]], [r.sec[k+1][0], r.sec[k+1][1] + 0.3, r.sec[k+1][2]], 0.4, 3); } }
    // outer wall down to the ground, the concourse top
    { const top = rows.map(r => r.sec[5]), bot = rows.map(r => { const p = r.sec[5]; return [p[0], Math.min(G(p[0], p[2]), P0) - 2.5, p[2]]; });
      loftP(B.p(CON), [bot, top]); const lip = rows.map(r => { const p = r.at(1.03, 0); return [p[0], r.sec[5][1] + 1.4, p[2]]; }); loftP(B.p('#e6e3dc'), [top, lip]);
      bandsP(B.p('#9a9890'), rows.map(r => [r.sec[5][0], r.sec[5][2]]), P0 - 30, P0 - 1, 4.5, 0.5, 0.12); }
