SG_PLACES.push({type:'hkstadium', lat:STD.lat, lon:STD.lon, rot:0});

// =====================================================================================================================
// One Island East (2008, Wong & Ouyang): the rounded-corner square tower on its OSM footprint (set diagonally to the streets), blue
// glass with vertical mullions, the top floor at 281.2 m and the crown screens to 298.4 m (Wikipedia), lit crown.
// =====================================================================================================================
const OIE = {lat:22.286093, lon:114.213384};
LANDMARKS.hkoneislandeast = {zh:'港岛东中心', en:'One Island East', cat:'new', r:36, h:299,
  lt:{m:1, c:'#e8f1ff', k:0.75},
  build(){
    const g = new THREE.Group(), B = mkB(), G = mkG(OIE.lat, OIE.lon);
    const R = D.oie, y0 = gMin(G, R) - 2.5, gs = gMin(G, R);
    const GL = {c:'#6f8ea6', m:1, fh:4.0, cw:3.0}, MUL = '#d6dde2', SPN = '#9fb2c0';
    // lobby (glass, set back), shaft, crown
    prismP(B.p('#9b9a95'), R, y0, gs + 0.4);
    prismP(B.p({c:'#5d6a72', glow:'#ffe2b6', gk:0.5}), offP(R, 1.2), gs + 0.4, gs + 14, true);
    prismP(B.p(GL), R, gs + 14, gs + 281.2, false, true);
    bandsP(B.p(SPN), R, gs + 14, gs + 281.2, 4.0, 0.45, 0.08);
    mullP(B.p(MUL), R, gs + 14, gs + 281.2, 1.6, 0.14, 0.12);
    bandsP(B.p('#c3ccd2'), R, gs + 14, gs + 281.2, 66, 4.0, 0.15);
    // crown: the four flat faces rise as screens to the top; the rounded corners stop lower
    const faces = []; for (let i = 0; i < R.length; i++){ const a = R[i], b = R[(i+1) % R.length]; if (Math.hypot(b[0]-a[0], b[1]-a[1]) > 15) faces.push([a, b]); }
    const CR = {c:'#8fa9bd', m:1, fh:4.0, cw:3.0};
    prismP(B.p(CR), offP(R, 0.6), gs + 281.2, gs + 287.5);
    for (const [a, b] of faces){ const n = [b[1] - a[1], -(b[0] - a[0])], L = Math.hypot(n[0], n[1]); const nx = n[0]/L*(area2(R) > 0 ? 1 : -1), nz = n[1]/L*(area2(R) > 0 ? 1 : -1);
      const p = [a[0] + nx*0.1, a[1] + nz*0.1], q = [b[0] + nx*0.1, b[1] + nz*0.1];
      quadP(B.p(CR), [p[0], gs + 281.2, p[1]], [q[0], gs + 281.2, q[1]], [q[0], gs + 298.4, q[1]], [p[0], gs + 298.4, p[1]]);
      mullP(B.p(MUL), [p, q], gs + 287.5, gs + 298.4, 1.6, 0.14, 0.05, i => i === 0);
      segP(B.p({c:'#e9f2ff', glow:'#eef6ff', gk:1.4}), [p[0], gs + 298.2, p[1]], [q[0], gs + 298.2, q[1]], 0.25, 3); }
    LCyl(g, 6, 6, 4, 0, gs + 287.5, 0, '#a7adb2', 12);
    LSph(g, 0.5, 0, gs + 292, 0, {c:'#c22', glow:'#ff2a1a', gk:2.2}, 1, 6);
    B.flush(g); return g; }};
SG_PLACES.push({type:'hkoneislandeast', lat:OIE.lat, lon:OIE.lon, rot:0});

